/**
 * @param {Array<Function>} functions
 * @param {number} ms
 * @return {Array<Function>}
 */
var delayAll = function(functions, ms) {
    // Helper that returns a promise resolving after ms milliseconds
    const delay = () => new Promise((resolve) => setTimeout(resolve, ms));

    return functions.map((fn) => {
        // `fn` is captured per iteration by the arrow callback's parameter
        return async function () {
            let result;
            try {
                // Await the original promise (also catches synchronous throws from fn)
                result = await fn();
            } catch (err) {
                // Wait the extra delay, then re-reject with the same error
                await delay();
                throw err;
            }
            // Wait the extra delay, then resolve with the same value
            await delay();
            return result;
        };
    });
};
